export const TOURNAMENT_DETAILS = new Map(
  [...UCL_KNOCKOUT_MATCHES, ...CUP_KNOCKOUT_MATCHES, ...WORLD_CUP_MATCHES].map((match) => [
    match.id,
    match,
  ]),
);

export const UCL_SEASONS = [TOURNAMENT_SEASON];
export const CUP_SEASONS = [TOURNAMENT_SEASON];
